import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    // Anagram signature: the sorted letters packed in base 27 (names have at most 10 letters).
    static long signature(String s) {
        char[] c = s.toCharArray();
        Arrays.sort(c);
        long key = 0;
        for (char ch : c) key = key * 27 + (ch - 'a' + 1);
        return key;
    }

    // Number of elements of the sorted array that are < x.
    static int lowerBound(long[] a, long x) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        String[] real = new String[n];
        for (int i = 0; i < n; i++) real[i] = next();
        long[] keys = new long[m];
        for (int i = 0; i < m; i++) keys[i] = signature(next());
        Arrays.sort(keys);
        List<String> out = new ArrayList<>();
        for (String s : real) {
            long k = signature(s);
            if (lowerBound(keys, k + 1) - lowerBound(keys, k) > 1) out.add(s);
        }
        Collections.sort(out);
        System.out.println(out.isEmpty() ? "None" : String.join(" ", out));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
	"sort"
	"strings"
)

// Anagram signature: the sorted letters packed in base 27 (names have at most 10 letters).
func signature(s []byte) int64 {
	c := slices.Clone(s)
	slices.Sort(c)
	var key int64
	for _, ch := range c {
		key = key*27 + int64(ch-'a'+1)
	}
	return key
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	real := make([]string, n)
	for i := range real {
		real[i] = string(nextToken())
	}
	keys := make([]int64, m)
	for i := range keys {
		keys[i] = signature(nextToken())
	}
	slices.Sort(keys)
	var out []string
	for _, s := range real {
		k := signature([]byte(s))
		lo := sort.Search(m, func(i int) bool { return keys[i] >= k })
		hi := sort.Search(m, func(i int) bool { return keys[i] > k })
		if hi-lo > 1 {
			out = append(out, s)
		}
	}
	slices.Sort(out)
	if len(out) == 0 {
		fmt.Println("None")
		return
	}
	fmt.Println(strings.Join(out, " "))
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
